// Timed classification drills: a random product, change and set of facts, generated by
// walking a region's tree with random answers, so every drill has one right answer.
import { CHANGES, regionOf, questionText, optionsFor, categoryOf, packFor } from './packs.js';
import { productAnswers, classify, isFromProduct, answerOf } from './classify.js';
import { BUILTIN_PRODUCTS } from './model.js';

export function rng(seed) {
  let s = seed >>> 0 || 1;
  return () => { s ^= s << 13; s >>>= 0; s ^= s >> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; };
}
const pick = (arr, r) => arr[Math.floor(r() * arr.length)];
const applies = (c, p) => c.scope === 'all' || (c.scope === 'bio' && p.facts.bio) || (c.scope === 'small' && !p.facts.bio) || (c.scope === 'sterile' && p.facts.sterile);

export function makeDrill(region, seed) {
  const r = rng(seed);
  const pack = packFor(region);
  for (let tries = 0; tries < 50; tries++) {
    const product = pick(BUILTIN_PRODUCTS.filter((p) => !['ca', 'ch', 'jp', 'who'].includes(region) || p[region]), r);
    const change = pick(CHANGES.filter((c) => applies(c, product) && pack.entries[c.id]), r);
    if (!change) continue;
    const answers = { ...productAnswers(product) };
    let node = pack.entries[change.id].tree;
    const facts = [];
    while (node && !node.cat) {
      if (node.allOf) {
        let failed = false;
        for (const q of node.allOf) {
          const auto = answerOf(pack, q, answers);
          const a = auto === 'yes' || auto === 'no' ? auto : (r() < 0.75 ? 'yes' : 'no');
          answers[q] = a;
          if (!isFromProduct(pack, q)) facts.push({ text: questionText(pack, q), answer: a === 'yes' ? 'Met' : 'Not met' });
          if (a === 'no') { failed = true; break; }
        }
        node = failed ? node.fail : node.pass;
        continue;
      }
      const given = answerOf(pack, node.ask, answers);
      const opts = optionsFor(node.ask);
      const a = given && node.on[given] ? given : pick(opts, r).value;
      answers[node.ask] = a;
      if (!isFromProduct(pack, node.ask)) facts.push({ text: questionText(pack, node.ask), answer: opts.find((o) => o.value === a)?.label ?? a });
      node = node.on[a];
    }
    const res = classify(pack, change.id, answers);
    if (res.status !== 'done') continue;
    return { region, regionLabel: regionOf(region).label, pack, product, change, facts, answer: res.category, outcome: res.outcome, options: pack.categories.filter((c) => !['OTHER'].includes(c.id) || res.category === 'OTHER') };
  }
  return null;
}

export function drillSet(region, n, seed) {
  const r = rng(seed);
  const out = [];
  for (let i = 0; i < n * 3 && out.length < n; i++) {
    const d = makeDrill(region, Math.floor(r() * 2 ** 31));
    if (d && !out.some((x) => x.change.id === d.change.id && x.product.id === d.product.id)) out.push(d);
  }
  return out;
}

export const categoryLabel = (pack, id) => categoryOf(pack, id)?.label ?? id;
